public class Sheet {

    @Id
    private String id;

    private LocalDate anchor;

    protected Sheet() {
    }

    public Sheet(String id) {
        this.id = id;
    }

    public String getId() {
        return id;
    }

    public LocalDate getAnchor() {
        return anchor;
    }
}
